UPDATE runtime_operations SET delivered_artifact_count=delivered_artifact_count+(SELECT artifact_count FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sent'),delivered_message_id=CASE WHEN delivered_artifact_count+(SELECT artifact_count FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sent')=planned_artifact_count THEN ?7 ELSE NULL END,status=CASE WHEN delivered_artifact_count+(SELECT artifact_count FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sent')=planned_artifact_count THEN 'succeeded' ELSE 'delivering' END,worker_id=CASE WHEN delivered_artifact_count+(SELECT artifact_count FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sent')=planned_artifact_count THEN NULL ELSE worker_id END,lease_token=CASE WHEN delivered_artifact_count+(SELECT artifact_count FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sent')=planned_artifact_count THEN NULL ELSE lease_token END,lease_expires_at=CASE WHEN delivered_artifact_count+(SELECT artifact_count FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sent')=planned_artifact_count THEN NULL ELSE lease_expires_at END,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status='delivering' AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER) AND EXISTS(SELECT 1 FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sent') AND delivered_artifact_count=COALESCE((SELECT SUM(artifact_count) FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND status='sent' AND ordinal<>?5),0);